package com.axelixlabs.axelix.master.api.external;

import java.lang.annotation.Documented;
import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * The annotation that signals that this field is indeed required, and it will alsways present, but only since
 * a given version of Axelix starter.
 *
 * @author Mikhail Polivakha
 */
@Documented
@Target(ElementType.FIELD)
@Retention(RetentionPolicy.SOURCE)
public @interface RequiredSince {

    /**
     * Version of Axelix starter components since which this field is actually required.
     */
    String value();
}
